-- J12 READ-ONLY: 166 composite source / owner consent / admin ACL / no data loss.
SELECT
(SELECT expected_skills=166 AND theory_skills=154 AND lab_skills=12 AND sources_total=166 FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS full_package_166,
(SELECT source_snapshot_md5~'^[a-f0-9]{32}$' FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS latest_source_digest_valid,
(SELECT full_package_source_integrity FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS theory_and_lab_coverage,
(SELECT NOT generic_publisher_compatible FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS generic_publisher_incompatibility,
(SELECT NOT owner_explicit_GO FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS owner_GO_missing,
(SELECT NOT armed FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS owner_custody_unarmed,
(SELECT NOT rights_reviewed FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS rights_signoff_missing,
(SELECT NOT backup_restore_tested FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS backup_restore_signoff_missing,
(SELECT NOT lab_delivery_tested FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS lab_delivery_signoff_missing,
(SELECT NOT tutor_access_isolated FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS tutor_isolation_signoff_missing,
(SELECT NOT actual_device_QA_done FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS device_acceptance_signoff_missing,
(SELECT content_exactly_approved IS NOT TRUE FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS source_not_approved,
(SELECT can_publish IS NOT TRUE FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS publisher_stays_blocked,
(SELECT release_not_yet_validated FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS release_not_validated,
(SELECT active_version IS NULL FROM private.iclub_subject_library WHERE subject_key='chemistry') AS active_version_null,
(SELECT currently_hidden FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS library_hidden,
(SELECT core_disabled FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS core_closed,
(SELECT entry_disabled FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS entry_closed,
(SELECT recheck_disabled FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS recheck_closed,
(SELECT p1_disabled FROM private.iclub_exam_chemistry_j12_release_gate_v1) AS p1_closed,
(SELECT consumed_at IS NULL AND published_at IS NULL AND hidden_at IS NULL FROM private.iclub_exam_chemistry_j12_release_control_v1 WHERE id=1) AS control_never_consumed,
(SELECT count(*)=0 FROM private.iclub_subject_library_release_events WHERE subject_key='chemistry') AS no_publish_events,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_entry_release_items_v1) AND (SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_release_items_v1) AND (SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_owner_release_items_v1) AS no_release_approvals,
(SELECT count(*)=12 FROM private.iclub_subject_library_cross_tour_v1 WHERE subject_key='chemistry' AND state='draft') AS lab_still_draft,
(SELECT count(*)=154 FROM private.iclub_subject_library_theory WHERE subject_key='chemistry') AS theory_154_unchanged,
(SELECT count(*)=462 FROM private.iclub_subject_library_tutor WHERE subject_key='chemistry') AS tutor_462_unchanged,
(SELECT count(*)=12 FROM private.iclub_subject_library_cross_tour_v1 WHERE subject_key='chemistry') AS LAB_12_unchanged,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_entry_attempts_v1) AS entry_attempts_zero,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_recheck_attempts_v1) AS recheck_attempts_zero,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_live_attempts_v1) AS P1_attempts_zero,
(SELECT count(*)=0 FROM private.iclub_exam_chemistry_p1_beta_members_v1) AS beta_members_zero,
(SELECT count(*)=45 FROM private.iclub_exam_core_chemistry_p1_secure_drafts_v1) AS old_P1_45_retained,
(SELECT count(*)=26 FROM private.iclub_exam_core_chemistry_p1_quarantine_v1) AS old_26_retained,
(SELECT count(*)=22 FROM private.iclub_exam_chemistry_entry_items_v1) AS entry_22_retained,
(SELECT count(*)=22 FROM private.iclub_exam_chemistry_recheck_items_v1) AS recheck_22_retained,
(SELECT relrowsecurity AND relforcerowsecurity FROM pg_class WHERE oid='private.iclub_exam_chemistry_j12_release_control_v1'::regclass) AS RLS_control,
NOT has_table_privilege('anon','private.iclub_exam_chemistry_j12_release_control_v1','SELECT') AS anon_control_denied,
NOT has_table_privilege('authenticated','private.iclub_exam_chemistry_j12_release_control_v1','SELECT') AS auth_control_denied,
NOT has_table_privilege('anon','private.iclub_exam_chemistry_j12_release_gate_v1','SELECT') AS anon_preflight_denied,
NOT has_table_privilege('authenticated','private.iclub_exam_chemistry_j12_release_gate_v1','SELECT') AS auth_preflight_denied,
NOT has_function_privilege('anon','private.iclub_exam_chemistry_j12_admin_publish_v1(text,text,text,text)','EXECUTE') AS publish_anon_denied,
NOT has_function_privilege('authenticated','private.iclub_exam_chemistry_j12_admin_publish_v1(text,text,text,text)','EXECUTE') AS publish_auth_denied,
NOT has_function_privilege('service_role','private.iclub_exam_chemistry_j12_admin_publish_v1(text,text,text,text)','EXECUTE') AS publish_service_denied,
NOT has_function_privilege('anon','private.iclub_exam_chemistry_j12_admin_hide_v1(text)','EXECUTE') AS hide_anon_denied,
NOT has_function_privilege('authenticated','private.iclub_exam_chemistry_j12_admin_hide_v1(text)','EXECUTE') AS hide_auth_denied,
NOT has_function_privilege('service_role','private.iclub_exam_chemistry_j12_admin_hide_v1(text)','EXECUTE') AS hide_service_denied,
(SELECT NOT p.prosecdef FROM pg_proc p WHERE p.oid='private.iclub_exam_chemistry_j12_admin_publish_v1(text,text,text,text)'::regprocedure) AS publisher_not_definer,
(SELECT NOT p.prosecdef FROM pg_proc p WHERE p.oid='private.iclub_exam_chemistry_j12_admin_hide_v1(text)'::regprocedure) AS hide_not_definer,
(SELECT count(*)>=544 FROM private.exam_prep_sessions) AS math_sessions_preserved,
(SELECT count(*)>=1979 FROM private.exam_prep_responses) AS math_responses_preserved,
(SELECT count(*)>=502 FROM public.practice_attempts) AS practice_attempts_preserved,
(SELECT count(*)>=4816 FROM public.practice_answers) AS practice_answers_preserved,
(SELECT count(*)>=1 FROM private.iclub_exam_native_mcq_attempts_v1) AS economics_attempts_preserved,
(SELECT count(*)>=2098 FROM public.user_subjects) AS subject_choices_preserved;